CREATE TABLE app_users (id BIGSERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(180) UNIQUE NOT NULL, password_hash VARCHAR(100) NOT NULL, role VARCHAR(32) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE projects (id BIGSERIAL PRIMARY KEY, project_code VARCHAR(24) UNIQUE NOT NULL, title VARCHAR(200) NOT NULL, description TEXT, category VARCHAR(100) NOT NULL, department VARCHAR(120) NOT NULL, owner_id BIGINT REFERENCES app_users(id), objectives TEXT, expected_outcomes TEXT, timeline_months INT NOT NULL DEFAULT 12, investment NUMERIC(16,2) NOT NULL CHECK(investment >= 0), annual_revenue NUMERIC(16,2) NOT NULL DEFAULT 0, annual_cost NUMERIC(16,2) NOT NULL DEFAULT 0, lifespan_years INT NOT NULL DEFAULT 5, strategic_importance INT NOT NULL DEFAULT 70, technical_feasibility INT NOT NULL DEFAULT 70, status VARCHAR(32) NOT NULL DEFAULT 'SUBMITTED', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_projects_status ON projects(status); CREATE INDEX idx_projects_category ON projects(category);
CREATE TABLE cash_flows (id BIGSERIAL PRIMARY KEY, project_id BIGINT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, year INT NOT NULL, amount NUMERIC(16,2) NOT NULL, UNIQUE(project_id,year));
CREATE TABLE evaluation_criteria (id BIGSERIAL PRIMARY KEY, name VARCHAR(100) UNIQUE NOT NULL, weight NUMERIC(6,3) NOT NULL CHECK(weight >= 0 AND weight <= 100), enabled BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE evaluations (id BIGSERIAL PRIMARY KEY, project_id BIGINT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, evaluator_id BIGINT NOT NULL REFERENCES app_users(id), overall_score NUMERIC(6,2) NOT NULL, financial_score NUMERIC(6,2) NOT NULL, risk_score NUMERIC(6,2) NOT NULL, comments TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(project_id,evaluator_id));
CREATE TABLE evaluation_scores (id BIGSERIAL PRIMARY KEY, evaluation_id BIGINT NOT NULL REFERENCES evaluations(id) ON DELETE CASCADE, criterion_id BIGINT NOT NULL REFERENCES evaluation_criteria(id), score NUMERIC(6,2) NOT NULL CHECK(score BETWEEN 0 AND 100), UNIQUE(evaluation_id,criterion_id));
CREATE TABLE project_risks (id BIGSERIAL PRIMARY KEY, project_id BIGINT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, risk_type VARCHAR(40) NOT NULL, description TEXT NOT NULL, probability INT NOT NULL CHECK(probability BETWEEN 1 AND 5), impact INT NOT NULL CHECK(impact BETWEEN 1 AND 5), mitigation TEXT);
CREATE TABLE investment_budgets (id BIGSERIAL PRIMARY KEY, amount NUMERIC(16,2) NOT NULL CHECK(amount >= 0), discount_rate NUMERIC(7,5) NOT NULL DEFAULT 0.08, active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE investment_scenarios (id BIGSERIAL PRIMARY KEY, name VARCHAR(160) NOT NULL, strategy VARCHAR(40) NOT NULL, budget NUMERIC(16,2) NOT NULL, allocated NUMERIC(16,2) NOT NULL, expected_return NUMERIC(16,2) NOT NULL, portfolio_risk NUMERIC(8,2) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE investment_allocations (id BIGSERIAL PRIMARY KEY, scenario_id BIGINT NOT NULL REFERENCES investment_scenarios(id) ON DELETE CASCADE, project_id BIGINT NOT NULL REFERENCES projects(id), selected BOOLEAN NOT NULL, explanation TEXT NOT NULL, UNIQUE(scenario_id,project_id));
CREATE TABLE project_documents (id BIGSERIAL PRIMARY KEY, project_id BIGINT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, file_name VARCHAR(255) NOT NULL, content_type VARCHAR(120), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE evaluation_comments (id BIGSERIAL PRIMARY KEY, evaluation_id BIGINT NOT NULL REFERENCES evaluations(id) ON DELETE CASCADE, author_id BIGINT NOT NULL REFERENCES app_users(id), body TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE notifications (id BIGSERIAL PRIMARY KEY, user_id BIGINT REFERENCES app_users(id) ON DELETE CASCADE, message TEXT NOT NULL, read BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id BIGSERIAL PRIMARY KEY, user_id BIGINT REFERENCES app_users(id), action VARCHAR(120) NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_id BIGINT, details JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
